import{_ as t,c as h,o as i,a3 as o}from"./chunks/framework.Bjn2b43V.js";const l=JSON.parse('{"title":"Mục 2.1 – Thiết Bị Mạng","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.1-thiet-bi-mang.md","filePath":"chuong-2/2.1-thiet-bi-mang.md","lastUpdated":1774577994000}'),a={name:"chuong-2/2.1-thiet-bi-mang.md"};function r(g,n,c,e,s,u){return i(),h("div",null,[...n[0]||(n[0]=[o(`<h1 id="muc-2-1-–-thiet-bi-mang" tabindex="-1">Mục 2.1 – Thiết Bị Mạng <a class="header-anchor" href="#muc-2-1-–-thiet-bi-mang" aria-label="Permalink to &quot;Mục 2.1 – Thiết Bị Mạng&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-can-biet-ve-thiet-bi-mang" tabindex="-1">Tại sao cần biết về thiết bị mạng? <a class="header-anchor" href="#tai-sao-can-biet-ve-thiet-bi-mang" aria-label="Permalink to &quot;Tại sao cần biết về thiết bị mạng?&quot;">​</a></h3><p>Hãy tưởng tượng buổi sáng bạn mở điện thoại lên, mở YouTube xem video – chỉ trong vài giây, hình ảnh và âm thanh từ máy chủ ở tận Mỹ xuất hiện ngay trên màn hình. Điều đó xảy ra được là nhờ <strong>một chuỗi thiết bị mạng</strong> làm việc phối hợp với nhau trong im lặng.</p><p>Thử nghĩ về bưu điện trong cuộc sống thực:</p><ul><li><strong>Modem</strong> giống như cổng ra vào của tòa nhà – nơi thư từ bên ngoài đi vào.</li><li><strong>Router</strong> giống như nhân viên bưu điện – họ đọc địa chỉ và quyết định thư đi về hướng nào.</li><li><strong>Switch</strong> giống như thùng thư nội bộ trong tòa nhà – phân phát đúng tầng, đúng phòng.</li><li><strong>Access Point</strong> giống như loa phát thanh không dây – để ai trong phạm vi cũng nhận được tín hiệu.</li></ul><p>Nếu không có những thiết bị này, máy tính của bạn sẽ là một hòn đảo cô lập – không thể nói chuyện với ai.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-switch-bo-chuyen-mach" tabindex="-1">2.1 Switch (Bộ chuyển mạch) <a class="header-anchor" href="#_2-1-switch-bo-chuyen-mach" aria-label="Permalink to &quot;2.1 Switch (Bộ chuyển mạch)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Switch là thiết bị mạng dùng để <strong>kết nối nhiều thiết bị trong cùng một mạng nội bộ (LAN)</strong> với nhau.</p><ul><li>Hoạt động ở <strong>Tầng 2 (Data Link Layer)</strong> trong mô hình OSI.</li><li>Dùng <strong>địa chỉ MAC</strong> để nhận diện thiết bị.</li><li>Truyền dữ liệu <strong>trực tiếp từ thiết bị nguồn đến thiết bị đích</strong> mà không phát tán ra toàn mạng.</li><li>Có nhiều cổng (port): 8, 16, 24, 48 cổng.</li></ul><h3 id="_2-2-router-bo-đinh-tuyen" tabindex="-1">2.2 Router (Bộ định tuyến) <a class="header-anchor" href="#_2-2-router-bo-đinh-tuyen" aria-label="Permalink to &quot;2.2 Router (Bộ định tuyến)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Router là thiết bị kết nối <strong>các mạng khác nhau</strong> lại với nhau – điển hình là kết nối mạng nội bộ (LAN) với Internet (WAN).</p><ul><li>Hoạt động ở <strong>Tầng 3 (Network Layer)</strong> trong mô hình OSI.</li><li>Dùng <strong>địa chỉ IP</strong> để định tuyến gói tin.</li><li>Có khả năng <strong>NAT</strong> (Network Address Translation) – dịch địa chỉ IP nội bộ sang địa chỉ IP công cộng.</li><li>Có tính năng <strong>tường lửa</strong> (firewall) cơ bản.</li></ul><h3 id="_2-3-access-point-điem-truy-cap-khong-day" tabindex="-1">2.3 Access Point (Điểm truy cập không dây) <a class="header-anchor" href="#_2-3-access-point-điem-truy-cap-khong-day" aria-label="Permalink to &quot;2.3 Access Point (Điểm truy cập không dây)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Access Point (AP) là thiết bị <strong>phát sóng Wi-Fi</strong>, cho phép thiết bị không dây kết nối vào mạng có dây.</p><ul><li>Về bản chất, AP là một cầu nối giữa mạng có dây và thiết bị không dây.</li><li>Router Wi-Fi gia đình thường <strong>tích hợp sẵn Access Point</strong> bên trong.</li><li>Trong môi trường lớn (trường học, sân bay), người ta dùng nhiều AP riêng biệt để phủ sóng.</li></ul><h3 id="_2-4-modem-bo-đieu-giai" tabindex="-1">2.4 Modem (Bộ điều giải) <a class="header-anchor" href="#_2-4-modem-bo-đieu-giai" aria-label="Permalink to &quot;2.4 Modem (Bộ điều giải)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Modem viết tắt của <strong>Modulator-Demodulator</strong> – thiết bị chuyển đổi tín hiệu số của máy tính thành tín hiệu analog (hoặc quang) để truyền qua đường dây viễn thông, và ngược lại.</p><ul><li><strong>Modulate (điều chế):</strong> Chuyển tín hiệu số → tín hiệu analog để truyền đi.</li><li><strong>Demodulate (giải điều chế):</strong> Nhận tín hiệu analog → chuyển lại thành tín hiệu số.</li><li>Kết nối với nhà cung cấp dịch vụ Internet (ISP) qua đường cáp đồng, cáp quang, hoặc đường dây điện thoại.</li></ul><h3 id="_2-5-đia-chi-mac-media-access-control" tabindex="-1">2.5 Địa chỉ MAC (Media Access Control) <a class="header-anchor" href="#_2-5-đia-chi-mac-media-access-control" aria-label="Permalink to &quot;2.5 Địa chỉ MAC (Media Access Control)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Địa chỉ MAC là <strong>định danh vật lý duy nhất</strong> được gắn cố định vào card mạng của mỗi thiết bị khi sản xuất.</p><ul><li>Dài <strong>48 bit</strong>, viết dưới dạng 6 cặp số hex, ví dụ: <code>A4:C3:F0:85:AC:5D</code></li><li><strong>Không thể thay đổi</strong> (về lý thuyết) – gắn liền với phần cứng.</li><li>Chỉ có giá trị trong <strong>mạng nội bộ</strong> – không được định tuyến qua Internet.</li><li>Switch dùng MAC để xây dựng <strong>bảng MAC (MAC table)</strong> và chuyển frame đúng cổng.</li></ul><h3 id="_2-6-đia-chi-ip-internet-protocol" tabindex="-1">2.6 Địa chỉ IP (Internet Protocol) <a class="header-anchor" href="#_2-6-đia-chi-ip-internet-protocol" aria-label="Permalink to &quot;2.6 Địa chỉ IP (Internet Protocol)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Địa chỉ IP là <strong>địa chỉ logic</strong> được gán cho thiết bị để định danh trong mạng, có thể thay đổi tùy cấu hình.</p><ul><li><strong>IPv4:</strong> 32 bit, viết dạng 4 octet thập phân, ví dụ: <code>192.168.1.10</code></li><li><strong>IPv6:</strong> 128 bit, ví dụ: <code>2001:0db8:85a3::8a2e:0370:7334</code></li><li>Có hai loại: <ul><li><strong>IP công cộng (Public IP):</strong> Dùng trên Internet, duy nhất toàn cầu.</li><li><strong>IP nội bộ (Private IP):</strong> Dùng trong LAN, ví dụ dải <code>192.168.x.x</code>, <code>10.x.x.x</code>.</li></ul></li><li>Router dùng IP để <strong>định tuyến</strong> gói tin giữa các mạng.</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="thuc-chat-switch-va-router-la-gi" tabindex="-1">Thực chất Switch và Router là gì? <a class="header-anchor" href="#thuc-chat-switch-va-router-la-gi" aria-label="Permalink to &quot;Thực chất Switch và Router là gì?&quot;">​</a></h3><p><strong>Switch</strong> chỉ &quot;nhìn&quot; vào phần <strong>tên cụ thể của thiết bị</strong> (địa chỉ MAC) – giống như người đưa thư trong một tòa nhà, chỉ cần biết số phòng là đủ, không cần biết tòa nhà đó ở quận nào.</p><p><strong>Router</strong> thì &quot;nhìn&quot; vào <strong>địa chỉ toàn cầu</strong> (địa chỉ IP) – giống như bưu điện trung tâm, cần biết cả tên đường, quận, thành phố để quyết định gửi gói hàng đi đường nào là nhanh nhất.</p><p><strong>Modem</strong> là &quot;phiên dịch viên&quot; – nhà cung cấp mạng (ISP) dùng tín hiệu điện/quang trên đường dây, còn máy tính dùng tín hiệu số. Modem đứng giữa và dịch qua lại liên tục.</p><p><strong>Access Point</strong> là &quot;chiếc loa không dây&quot; – thay vì bắt bạn phải cắm dây, nó phát sóng ra xung quanh để thiết bị tự bắt tín hiệu.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="luong-du-lieu-tu-internet-đen-may-tinh-cua-ban" tabindex="-1">Luồng dữ liệu từ Internet đến máy tính của bạn <a class="header-anchor" href="#luong-du-lieu-tu-internet-đen-may-tinh-cua-ban" aria-label="Permalink to &quot;Luồng dữ liệu từ Internet đến máy tính của bạn&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Internet → Modem → Router → Switch → Thiết bị đầu cuối</span></span></code></pre></div><p><strong>Bước 1 – Internet đến Modem:</strong> Nhà cung cấp dịch vụ Internet (VNPT, Viettel, FPT...) truyền dữ liệu qua cáp quang/đồng đến nhà bạn. Modem nhận tín hiệu này và <strong>chuyển đổi thành tín hiệu số</strong> mà router có thể hiểu.</p><p><strong>Bước 2 – Modem đến Router:</strong> Router nhận dữ liệu từ modem, đọc <strong>địa chỉ IP đích</strong>, xác định xem gói tin đó thuộc về thiết bị nào trong mạng nội bộ.</p><p><strong>Bước 3 – Router đến Switch:</strong> Router chuyển gói tin vào mạng nội bộ. Nếu là kết nối có dây, gói tin đến <strong>Switch</strong>. Router biết thiết bị đó có IP nội bộ là <code>192.168.1.5</code>, chuyển gói đến switch.</p><p><strong>Bước 4 – Switch đến Thiết bị:</strong> Switch tra <strong>bảng MAC</strong> để biết địa chỉ MAC của thiết bị có IP <code>192.168.1.5</code> đang ở cổng số mấy, rồi chuyển frame <strong>chính xác đến cổng đó</strong> – không phát tán sang các thiết bị khác.</p><p><strong>Bước 5 – Thiết bị nhận dữ liệu:</strong> Máy tính/điện thoại nhận frame, xử lý và hiển thị kết quả (trang web, video, email...).</p><blockquote><p><strong>Nếu dùng Wi-Fi:</strong> Bước 3-4 thay bằng Router/Access Point phát sóng Wi-Fi trực tiếp đến thiết bị.</p></blockquote><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-mang-tai-nha" tabindex="-1">Ví dụ 1 – Cơ bản: Mạng tại nhà <a class="header-anchor" href="#vi-du-1-–-co-ban-mang-tai-nha" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Mạng tại nhà&quot;">​</a></h3><p>Nhà bạn có: 1 modem, 1 router Wi-Fi, 1 switch 8 cổng, 3 máy tính, 2 điện thoại.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Internet/ISP]</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>   [Modem]        ← Nhận tín hiệu từ ISP, chuyển đổi tín hiệu</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>   [Router]       ← Phân chia mạng nội bộ, cấp IP cho thiết bị</span></span>
<span class="line"><span>    /    \\</span></span>
<span class="line"><span>[Switch] [Wi-Fi AP]</span></span>
<span class="line"><span>  / | \\      |  \\</span></span>
<span class="line"><span>[PC1][PC2][PC3] [Phone1][Phone2]</span></span></code></pre></div><ul><li>PC1, PC2, PC3 cắm dây vào switch → switch dùng MAC để phân phát.</li><li>Phone1, Phone2 kết nối Wi-Fi → router/AP dùng IP để định tuyến.</li></ul><h3 id="vi-du-2-–-thuc-te-quan-ca-phe" tabindex="-1">Ví dụ 2 – Thực tế: Quán cà phê <a class="header-anchor" href="#vi-du-2-–-thuc-te-quan-ca-phe" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Quán cà phê&quot;">​</a></h3><p>Quán cà phê có 30 khách hàng dùng Wi-Fi cùng lúc:</p><ul><li><strong>1 modem</strong> kết nối đường truyền cáp quang từ ISP.</li><li><strong>1 router</strong> quản lý toàn bộ mạng, cấp IP tự động cho khách (DHCP).</li><li><strong>3 Access Point</strong> đặt ở 3 góc quán để phủ sóng đồng đều.</li><li>Mỗi khách có <strong>IP nội bộ</strong> riêng (ví dụ: <code>192.168.1.100</code> đến <code>192.168.1.130</code>).</li><li>Tất cả dùng <strong>1 IP công cộng</strong> duy nhất khi ra Internet (nhờ NAT của router).</li></ul><h3 id="vi-du-3-–-nang-cao-truong-hoc" tabindex="-1">Ví dụ 3 – Nâng cao: Trường học <a class="header-anchor" href="#vi-du-3-–-nang-cao-truong-hoc" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Trường học&quot;">​</a></h3><p>Trường có 40 phòng học, mỗi phòng 30 máy tính:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ISP - Cáp quang tốc độ cao]</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>    [Modem quang]</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>  [Router trung tâm]  ← IP công cộng, kết nối Internet</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>  [Core Switch]       ← Switch tốc độ cao, kết nối toàn trường</span></span>
<span class="line"><span>    /    |    \\</span></span>
<span class="line"><span>[Switch  Switch  Switch...]  ← Mỗi switch cho 1 dãy phòng</span></span>
<span class="line"><span>  |        |</span></span>
<span class="line"><span>[PC phòng 1] [PC phòng 2]...</span></span></code></pre></div><ul><li>Địa chỉ IP được chia thành các <strong>subnet</strong> riêng: phòng lab (<code>192.168.10.x</code>), phòng giáo viên (<code>192.168.20.x</code>), thư viện (<code>192.168.30.x</code>).</li><li><strong>VLAN</strong> (mạng ảo) giúp tách biệt lưu lượng giữa các khu vực.</li></ul><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="switch-vs-router" tabindex="-1">Switch vs Router <a class="header-anchor" href="#switch-vs-router" aria-label="Permalink to &quot;Switch vs Router&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Switch</th><th>Router</th></tr></thead><tbody><tr><td><strong>Chức năng chính</strong></td><td>Kết nối thiết bị trong LAN</td><td>Kết nối các mạng khác nhau</td></tr><tr><td><strong>Địa chỉ sử dụng</strong></td><td>Địa chỉ MAC</td><td>Địa chỉ IP</td></tr><tr><td><strong>Tầng OSI</strong></td><td>Tầng 2 (Data Link)</td><td>Tầng 3 (Network)</td></tr><tr><td><strong>Phạm vi hoạt động</strong></td><td>Chỉ trong LAN</td><td>LAN ↔ WAN (Internet)</td></tr><tr><td><strong>Có DHCP không?</strong></td><td>Không</td><td>Có</td></tr><tr><td><strong>Ví dụ dùng ở đâu</strong></td><td>Kết nối máy tính trong văn phòng</td><td>Cổng vào Internet ở nhà</td></tr></tbody></table><h3 id="router-vs-modem" tabindex="-1">Router vs Modem <a class="header-anchor" href="#router-vs-modem" aria-label="Permalink to &quot;Router vs Modem&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Router</th><th>Modem</th></tr></thead><tbody><tr><td><strong>Chức năng</strong></td><td>Phân phối và định tuyến mạng</td><td>Chuyển đổi tín hiệu</td></tr><tr><td><strong>Kết nối với ai</strong></td><td>Kết nối LAN và ISP</td><td>Kết nối trực tiếp với ISP</td></tr><tr><td><strong>Địa chỉ IP</strong></td><td>Quản lý IP nội bộ</td><td>Nhận IP công cộng từ ISP</td></tr><tr><td><strong>Tường lửa</strong></td><td>Có</td><td>Không</td></tr><tr><td><strong>Thiếu cái này thì sao?</strong></td><td>Mạng không phân phối được</td><td>Không kết nối được với ISP</td></tr></tbody></table><h3 id="đia-chi-mac-vs-đia-chi-ip" tabindex="-1">Địa chỉ MAC vs Địa chỉ IP <a class="header-anchor" href="#đia-chi-mac-vs-đia-chi-ip" aria-label="Permalink to &quot;Địa chỉ MAC vs Địa chỉ IP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>MAC Address</th><th>IP Address</th></tr></thead><tbody><tr><td><strong>Loại địa chỉ</strong></td><td>Vật lý (gắn với phần cứng)</td><td>Logic (có thể thay đổi)</td></tr><tr><td><strong>Cố định?</strong></td><td>Có (do nhà sản xuất gán)</td><td>Không (cấp bởi DHCP hoặc cấu hình tay)</td></tr><tr><td><strong>Dùng ở tầng nào</strong></td><td>Tầng 2</td><td>Tầng 3</td></tr><tr><td><strong>Phạm vi</strong></td><td>Chỉ trong LAN</td><td>Cả LAN lẫn Internet</td></tr><tr><td><strong>Ví dụ</strong></td><td><code>A4:C3:F0:85:AC:5D</code></td><td><code>192.168.1.10</code></td></tr><tr><td><strong>Thiết bị nào dùng</strong></td><td>Switch</td><td>Router</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🔵 <strong>Switch</strong> = kết nối <strong>trong LAN</strong> + dùng <strong>MAC</strong> address</li><li>🟢 <strong>Router</strong> = kết nối <strong>giữa các mạng</strong> + dùng <strong>IP</strong> address</li><li>🟡 <strong>Modem</strong> = chuyển đổi tín hiệu <strong>số ↔ analog</strong> để kết nối ISP</li><li>🔴 <strong>Access Point</strong> = phát <strong>Wi-Fi</strong>, cầu nối mạng có dây – không dây</li><li>📍 <strong>MAC</strong> = địa chỉ <strong>vật lý</strong>, <strong>cố định</strong>, dạng <code>XX:XX:XX:XX:XX:XX</code> (48 bit, hex)</li><li>📍 <strong>IP</strong> = địa chỉ <strong>logic</strong>, <strong>có thể thay đổi</strong>, dạng <code>X.X.X.X</code> (IPv4, 32 bit)</li><li>🔁 <strong>Luồng chuẩn:</strong> Internet → <strong>Modem</strong> → <strong>Router</strong> → <strong>Switch</strong> → Thiết bị</li><li>⚡ Switch dùng <strong>MAC table</strong> để chuyển frame đúng cổng (không phát tán)</li><li>⚡ Router dùng <strong>routing table</strong> để chuyển gói đúng mạng</li><li>🏠 Router thường <strong>tích hợp</strong> Switch + Access Point trong thiết bị gia đình</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-đien-vao-cho-trong" tabindex="-1">Câu 1 (Dễ): Điền vào chỗ trống <a class="header-anchor" href="#cau-1-de-đien-vao-cho-trong" aria-label="Permalink to &quot;Câu 1 (Dễ): Điền vào chỗ trống&quot;">​</a></h3><blockquote><p>Switch sử dụng địa chỉ _______ để chuyển dữ liệu, trong khi Router sử dụng địa chỉ _______.</p></blockquote><p><strong>Đáp án:</strong> Switch dùng <strong>MAC</strong>, Router dùng <strong>IP</strong>.</p><p><strong>Giải thích:</strong> Switch hoạt động ở tầng 2, chỉ quan tâm đến định danh vật lý (MAC) trong mạng nội bộ. Router hoạt động ở tầng 3, dùng IP để định tuyến giữa các mạng.</p><hr><h3 id="cau-2-de-trac-nghiem" tabindex="-1">Câu 2 (Dễ): Trắc nghiệm <a class="header-anchor" href="#cau-2-de-trac-nghiem" aria-label="Permalink to &quot;Câu 2 (Dễ): Trắc nghiệm&quot;">​</a></h3><blockquote><p>Thiết bị nào có chức năng chuyển đổi tín hiệu số thành tín hiệu analog để truyền qua đường dây điện thoại? A. Switch B. Router C. Modem D. Access Point</p></blockquote><p><strong>Đáp án: C – Modem</strong></p><p><strong>Giải thích:</strong> Modem (Modulator-Demodulator) thực hiện điều chế (modulate) và giải điều chế (demodulate) tín hiệu. Đây là thiết bị duy nhất trong danh sách có chức năng chuyển đổi tín hiệu giữa hai định dạng khác nhau.</p><hr><h3 id="cau-3-trung-binh-phan-tich-tinh-huong" tabindex="-1">Câu 3 (Trung bình): Phân tích tình huống <a class="header-anchor" href="#cau-3-trung-binh-phan-tich-tinh-huong" aria-label="Permalink to &quot;Câu 3 (Trung bình): Phân tích tình huống&quot;">​</a></h3><blockquote><p>Nhà bạn có router Wi-Fi nhưng tốc độ mạng rất chậm khi nhiều thiết bị dùng cùng lúc. Bạn muốn mua thêm thiết bị để kết nối 10 máy tính bàn bằng dây mà không ảnh hưởng đến Wi-Fi. Bạn nên mua thiết bị gì?</p></blockquote><p><strong>Đáp án:</strong> Mua thêm <strong>Switch</strong>.</p><p><strong>Giải thích:</strong> Switch giúp mở rộng số lượng cổng kết nối có dây trong LAN mà không tiêu thụ băng thông Wi-Fi. Nó cắm vào một cổng LAN của router và cung cấp thêm nhiều cổng cho máy tính bàn kết nối bằng cáp Ethernet – nhanh hơn và ổn định hơn Wi-Fi.</p><hr><h3 id="cau-4-trung-binh-sap-xep-luong-du-lieu" tabindex="-1">Câu 4 (Trung bình): Sắp xếp luồng dữ liệu <a class="header-anchor" href="#cau-4-trung-binh-sap-xep-luong-du-lieu" aria-label="Permalink to &quot;Câu 4 (Trung bình): Sắp xếp luồng dữ liệu&quot;">​</a></h3><blockquote><p>Sắp xếp theo đúng thứ tự luồng dữ liệu từ Internet đến máy tính: [Router] – [Thiết bị đầu cuối] – [Modem] – [Switch] – [Internet/ISP]</p></blockquote><p><strong>Đáp án:</strong> Internet/ISP → Modem → Router → Switch → Thiết bị đầu cuối</p><p><strong>Giải thích:</strong></p><ul><li>ISP truyền tín hiệu đến <strong>Modem</strong> (chuyển đổi tín hiệu).</li><li>Modem kết nối với <strong>Router</strong> (định tuyến và phân phối IP).</li><li>Router chuyển vào mạng nội bộ qua <strong>Switch</strong> (phân phát theo MAC).</li><li>Switch đưa dữ liệu đến đúng <strong>Thiết bị đầu cuối</strong>.</li></ul><hr><h3 id="cau-5-van-dung-thiet-ke-mang" tabindex="-1">Câu 5 (Vận dụng): Thiết kế mạng <a class="header-anchor" href="#cau-5-van-dung-thiet-ke-mang" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Thiết kế mạng&quot;">​</a></h3><blockquote><p>Bạn được giao thiết kế mạng cho một văn phòng nhỏ gồm: 1 đường truyền cáp quang từ ISP, 20 máy tính bàn kết nối dây, 15 laptop kết nối Wi-Fi. Hãy liệt kê các thiết bị cần mua và giải thích vai trò của từng thiết bị.</p></blockquote><p><strong>Đáp án gợi ý:</strong></p><table tabindex="0"><thead><tr><th>Thiết bị</th><th>Số lượng</th><th>Vai trò</th></tr></thead><tbody><tr><td>Modem quang</td><td>1</td><td>Kết nối đường truyền ISP, chuyển đổi tín hiệu quang</td></tr><tr><td>Router</td><td>1</td><td>Phân phối mạng, cấp IP (DHCP), tường lửa, NAT</td></tr><tr><td>Switch 24 cổng</td><td>1</td><td>Kết nối 20 máy tính bàn bằng dây</td></tr><tr><td>Access Point</td><td>2-3</td><td>Phủ sóng Wi-Fi cho 15 laptop (tùy diện tích văn phòng)</td></tr></tbody></table><p><strong>Giải thích:</strong> Modem kết nối ISP → Router quản lý toàn mạng → Switch mở rộng cổng có dây → AP phủ sóng không dây. Dùng 2-3 AP để tránh nghẽn khi 15 laptop dùng cùng lúc.</p><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-switch-voi-hub" tabindex="-1">❌ Lỗi 1: Nhầm Switch với Hub <a class="header-anchor" href="#❌-loi-1-nham-switch-voi-hub" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm Switch với Hub&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Switch phát tán dữ liệu đến tất cả thiết bị trong mạng.&quot;</p><p><strong>Đúng:</strong> Switch <strong>chỉ gửi đến đúng thiết bị đích</strong> bằng cách tra bảng MAC. Hub mới phát tán (broadcast) đến tất cả – nhưng Hub gần như không còn được dùng ngày nay.</p><hr><h3 id="❌-loi-2-nham-router-voi-modem" tabindex="-1">❌ Lỗi 2: Nhầm Router với Modem <a class="header-anchor" href="#❌-loi-2-nham-router-voi-modem" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm Router với Modem&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Modem kết nối các máy tính trong nhà với nhau.&quot;</p><p><strong>Đúng:</strong> Modem chỉ làm nhiệm vụ <strong>chuyển đổi tín hiệu</strong> giữa ISP và mạng nhà. Chính <strong>Router</strong> mới là thiết bị kết nối và phân phối mạng nội bộ. (Lưu ý: nhiều thiết bị gia đình tích hợp cả hai trong một hộp, dễ nhầm lẫn.)</p><hr><h3 id="❌-loi-3-nghi-đia-chi-mac-co-the-dung-đe-đinh-tuyen-tren-internet" tabindex="-1">❌ Lỗi 3: Nghĩ địa chỉ MAC có thể dùng để định tuyến trên Internet <a class="header-anchor" href="#❌-loi-3-nghi-đia-chi-mac-co-the-dung-đe-đinh-tuyen-tren-internet" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ địa chỉ MAC có thể dùng để định tuyến trên Internet&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Router dùng địa chỉ MAC để gửi dữ liệu qua Internet.&quot;</p><p><strong>Đúng:</strong> MAC address <strong>chỉ có giá trị trong phạm vi LAN</strong>. Khi dữ liệu ra khỏi mạng nội bộ, Router dùng <strong>địa chỉ IP</strong> để định tuyến. MAC không bao giờ &quot;đi&quot; ra ngoài Internet.</p><hr><h3 id="❌-loi-4-nghi-ip-noi-bo-la-duy-nhat-toan-cau" tabindex="-1">❌ Lỗi 4: Nghĩ IP nội bộ là duy nhất toàn cầu <a class="header-anchor" href="#❌-loi-4-nghi-ip-noi-bo-la-duy-nhat-toan-cau" aria-label="Permalink to &quot;❌ Lỗi 4: Nghĩ IP nội bộ là duy nhất toàn cầu&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Địa chỉ 192.168.1.1 của router nhà tôi là duy nhất trên thế giới.&quot;</p><p><strong>Đúng:</strong> <code>192.168.x.x</code> là <strong>dải IP riêng tư (private IP)</strong>, có thể trùng ở hàng triệu nhà trên thế giới. Chỉ có <strong>IP công cộng (public IP)</strong> do ISP cấp mới là duy nhất. Tính duy nhất trong LAN là đủ, nhờ NAT của router.</p><hr><h3 id="❌-loi-5-nham-access-point-voi-router" tabindex="-1">❌ Lỗi 5: Nhầm Access Point với Router <a class="header-anchor" href="#❌-loi-5-nham-access-point-voi-router" aria-label="Permalink to &quot;❌ Lỗi 5: Nhầm Access Point với Router&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Access Point có thể thay thế hoàn toàn Router.&quot;</p><p><strong>Đúng:</strong> Access Point <strong>chỉ phát sóng Wi-Fi</strong> – không có khả năng định tuyến, NAT hay cấp IP (DHCP). Nếu không có Router phía sau, AP không thể kết nối Internet. Access Point chỉ là &quot;cây cầu không dây&quot;, Router mới là &quot;bộ não&quot; của mạng.</p>`,119)])])}const p=t(a,[["render",r]]);export{l as __pageData,p as default};
